  "class VerificarAfirmacion(dspy.Signature):\n    afirmacion: str = dspy.InputField()\n    fragmento: str = dspy.InputField()\n    encabezado: str = dspy.InputField()\n    veredicto: Literal[\"sostenida\", \"parcial\", \"no_sostenida\"] = dspy.OutputField()\n    motivo: str = dspy.OutputField()\n    entidad_distinta: bool = dspy.OutputField()\n\njuez = dspy.Predict(VerificarAfirmacion)\nwith dspy.context(lm=opus5):\n    dictamenes = [juez(**a) for a in afirmaciones_con_fragmento]\n\n# celda 14 (trayectoria r7): correlacion ASC vs p-tau217 en la cohorte piloto\nimport numpy as np\nr = np.corrcoef(piloto[\"asc_lcr\"], piloto[\"ptau217\"])[0, 1]  # 0.62": "class VerifyClaim(dspy.Signature):\n    claim: str = dspy.InputField()\n    excerpt: str = dspy.InputField()\n    heading: str = dspy.InputField()\n    verdict: Literal[\"supported\", \"partial\", \"not_supported\"] = dspy.OutputField()\n    reason: str = dspy.OutputField()\n    different_entity: bool = dspy.OutputField()\n\njudge = dspy.Predict(VerifyClaim)\nwith dspy.context(lm=opus5):\n    rulings = [judge(**a) for a in claims_with_excerpt]\n\n# cell 14 (r7 trajectory): ASC vs p-tau217 correlation in the pilot cohort\nimport numpy as np\nr = np.corrcoef(pilot[\"asc_lcr\"], pilot[\"ptau217\"])[0, 1]  # 0.62",
